const filter=process.env.PK_QA_FILTER?new RegExp(process.env.PK_QA_FILTER):null;
async function test(name,fn){if(filter&&!filter.test(name))return;try{const detail=await fn();report.checks.push({name,status:'PASS',detail});console.log('PASS '+name);}catch(e){report.checks.push({name,status:'FAIL',error:e.stack});console.error('FAIL '+name+': '+e.message);}}
async function setup(w=1366,h=768,extra={}){
 const c=await browser.newContext({viewport:{width:w,height:h},...extra});
 await c.route('**/*',route=>{const u=new URL(route.request().url());if(u.origin!==new URL(base).origin){report.external.push(u.origin);return route.abort();}return route.continue();});
 await c.addInitScript(()=>{window.__qaCsp=[];window.__qaCls=0;window.__qaLcp=0;document.addEventListener('securitypolicyviolation',e=>window.__qaCsp.push({directive:e.effectiveDirective,blocked:e.blockedURI}));try{new PerformanceObserver(es=>{for(const e of es.getEntries())if(!e.hadRecentInput)window.__qaCls+=e.value;}).observe({type:'layout-shift',buffered:true});new PerformanceObserver(es=>{for(const e of es.getEntries())window.__qaLcp=e.startTime;}).observe({type:'largest-contentful-paint',buffered:true});}catch{}});
 const p=await c.newPage();p.on('pageerror',e=>report.errors.push({message:e.message,stack:e.stack}));p.on('response',r=>{if(r.status()>=400)report.http.push({path:new URL(r.url()).pathname,status:r.status()});});return{c,p};
}
async function collect(p){report.csp.push(...await p.evaluate(()=>window.__qaCsp||[]));}
async function shot(p,name){const file=name+'.png';await p.screenshot({path:path.join(out,file)});report.captures.push(file);}
