async function geometry(p,label){const g=await p.evaluate(()=>{const box=e=>{if(!e)return null;const r=e.getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height,right:r.right,bottom:r.bottom};};const visible=e=>{const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.visibility!=='hidden'&&s.display!=='none'&&Number(s.opacity)>.1&&r.width>0&&r.height>0&&!e.closest('[inert]');};const boxes=[...document.querySelectorAll('.living-intro,.living-activation,.living-map-heading,.living-chapter__copy,.living-provenance,.living-reveal,.living-finale')].filter(visible).map(e=>({className:e.className,text:e.textContent.trim().slice(0,70),...box(e)}));const controls=[...document.querySelectorAll('.living-stage a,.living-stage button,.topbar button,.project-download-console a,.project-return')].filter(visible).filter(e=>{const r=e.getBoundingClientRect();return r.bottom>0&&r.y<innerHeight;}).map(e=>{const r=e.getBoundingClientRect(),x=r.x+r.width/2,y=r.y+r.height/2,hit=x>=0&&x<innerWidth&&y>=0&&y<innerHeight?document.elementFromPoint(x,y):null;return{text:e.textContent.trim().slice(0,50),hit:!!hit&&(hit===e||e.contains(hit)),...box(e)};});return{width:innerWidth,height:innerHeight,documentWidth:document.documentElement.scrollWidth,stage:box(document.querySelector('.living-stage')),logo:box(document.querySelector('.living-identity .core-brand')||document.querySelector('.living-identity img')),core:box(document.querySelector('.living-identity')),drone:box(document.querySelector('[data-drone-toggle]')),mode:document.querySelector('[data-living-journey]')?.dataset.scene,boxes,controls};});report.geometry.push({label,...g});assert(g.documentWidth<=g.width+1,`${label} horizontal overflow ${g.documentWidth}/${g.width}`);return g;}
async function fullLogo(p,label){await p.locator('.living-identity .core-brand,.living-identity>img').first().evaluate(e=>e.decode());const g=await geometry(p,label);assert(g.logo&&g.logo.x>=-1&&g.logo.y>=-1&&g.logo.right<=g.width+1&&g.logo.bottom<=g.height+1,`${label} logo outside viewport: ${JSON.stringify(g.logo)}`);return g;}
async function at(p,value){await p.evaluate(v=>{const r=document.querySelector('[data-living-journey]'),s=r.querySelector('.living-stage');scrollTo({top:r.getBoundingClientRect().top+scrollY+v*s.clientHeight,behavior:'instant'});},value);await p.waitForTimeout(180);}
async function map(p){const value=await p.locator('[data-living-journey]').getAttribute('data-progress');if(Number(value||0)<1.4&&await p.locator('[data-core-activate]').getAttribute('aria-pressed')!=='true')await p.locator('[data-core-activate]').click();await p.waitForFunction(()=>Number(document.querySelector('[data-living-journey]')?.dataset.progress||0)>1.43);await p.waitForTimeout(180);}
